const BASE_URL = 'https://nyaa.si';

function getMediaTitle(media) {
  return media?.title?.romaji || media?.title?.english || media?.title?.native || media?.romajiTitle || media?.englishTitle || media?.nativeTitle || '';
}

function getSettings() {
  return {
    canSmartSearch: true,
    smartSearchFilters: ['batch', 'episodeNumber', 'resolution', 'query'],
    supportsAdult: false,
    type: 'main'
  };
}

function normalizeSize(value) {
  if (!value) return 0;
  const match = String(value).trim().match(/^([0-9.]+)\s*(KiB|MiB|GiB|TiB|KB|MB|GB|TB|B)$/i);
  if (!match) return 0;
  const n = Number(match[1]);
  const unit = match[2].toUpperCase();
  const powers = { B: 0, KB: 1, MB: 2, GB: 3, TB: 4, KIB: 1, MIB: 2, GIB: 3, TIB: 4 };
  return Math.round(n * Math.pow(unit.endsWith('IB') ? 1024 : 1000, powers[unit] || 0));
}

function parseTorrentName(name) {
  const text = String(name || '');
  const resolution = (text.match(/(?:^|[\s._\-\[])(2160p|1440p|1080p|900p|720p|576p|480p|360p)(?:[\s._\-\]]|$)/i) || [])[1] || '';
  const batch = /(?:batch|complete|complete series|season(?:s)?)(?:[\s._\-]|$)/i.test(text);
  let episodeNumber = -1;
  const ep = text.match(/(?:^|[\s._\-\[])[Ee](?:pisode)?[\s._\-]*(\d{1,4})(?:[\s._\-\]]|$)/i) || text.match(/(?:^|[\s._\-\[])\d{1,3}\s*(?:[-~])\s*\d{1,3}(?:[\s._\-\]]|$)/);
  if (ep && ep[1]) episodeNumber = Number(ep[1]);
  const group = (text.match(/^\[([^\]]+)\]/) || [])[1] || '';
  return { resolution, episodeNumber, batch, releaseGroup: group };
}

function buildUrl(query, category, trustedOnly) {
  const params = new URLSearchParams();
  params.set('f', trustedOnly ? '2' : '0');
  params.set('c', category || '1_2');
  if (query) params.set('q', query);
  params.set('s', 'seeders');
  params.set('o', 'desc');
  return BASE_URL + '/?' + params.toString();
}

async function fetchAndParse(query, category, trustedOnly) {
  const html = await fetch(buildUrl(query, category, trustedOnly)).then(r => r.text());
  const doc = LoadDoc(html);
  const rows = doc.select('table.torrent-list tbody tr');
  const results = [];
  for (const row of rows) {
    const cells = row.select('td');
    if (!cells || cells.length < 8) continue;
    const titleLink = row.selectFirst('td:nth-child(2) a:not(.comments)');
    if (!titleLink) continue;
    const name = titleLink.text().trim();
    const torrentLink = row.selectFirst('a.torrent');
    const magnetLink = row.selectFirst('a[href^=magnet:]');
    const sizeText = cells[3]?.text()?.trim() || '';
    const dateText = cells[4]?.attr('data-timestamp') || '';
    const seeders = Number(cells[5]?.text()?.trim() || 0);
    const leechers = Number(cells[6]?.text()?.trim() || 0);
    const downloads = Number(cells[7]?.text()?.trim() || 0);
    const parsed = parseTorrentName(name);
    const link = titleLink.attr('href') || '';
    results.push({
      provider: 'nyaa-custom',
      name,
      date: dateText ? new Date(Number(dateText) * 1000) : new Date(),
      size: normalizeSize(sizeText),
      formattedSize: sizeText,
      seeders,
      leechers,
      downloadCount: downloads,
      link: link.startsWith('http') ? link : BASE_URL + link,
      downloadUrl: torrentLink?.attr('href') || '',
      magnetLink: magnetLink?.attr('href') || '',
      infoHash: '',
      resolution: parsed.resolution,
      isBatch: parsed.batch,
      episodeNumber: parsed.episodeNumber,
      releaseGroup: parsed.releaseGroup,
      isBestRelease: false
    });
  }
  return results;
}

async function search(opts) {
  const query = opts?.query || '';
  return fetchAndParse(query, opts?.userConfig?.category || '1_2', opts?.userConfig?.trustedOnly === true);
}

async function smartSearch(opts) {
  const title = getMediaTitle(opts?.media);
  let query = title;
  if (opts?.episodeNumber != null && opts.episodeNumber > 0) query += ' ' + opts.episodeNumber;
  if (opts?.resolution) query += ' ' + opts.resolution;
  const results = await fetchAndParse(query, opts?.userConfig?.category || '1_2', opts?.userConfig?.trustedOnly === true);
  return results.filter(x => {
    if (opts?.episodeNumber != null && opts.episodeNumber > 0 && !x.isBatch && x.episodeNumber > 0 && x.episodeNumber !== Number(opts.episodeNumber)) return false;
    if (opts?.resolution && x.resolution && x.resolution.toLowerCase() !== String(opts.resolution).toLowerCase()) return false;
    return true;
  });
}

async function getLatest(opts) {
  return fetchAndParse('', opts?.userConfig?.category || '1_2', opts?.userConfig?.trustedOnly === true);
}

async function getTorrentMagnetLink(torrent) {
  return torrent?.magnetLink || '';
}

async function getTorrentInfoHash(torrent) {
  const magnet = torrent?.magnetLink || '';
  const match = magnet.match(/btih:([^&/]+)/i);
  return match ? decodeURIComponent(match[1]).toLowerCase() : '';
}

return { getSettings, search, smartSearch, getLatest, getTorrentMagnetLink, getTorrentInfoHash };
